#!/bin/sh
# Creates the GitHub release so that GitHub disturbances do not break the last step of a release
# (2026-11-25: 5xx answers, softprops/action-gh-release gave up after 3 tries – "Too many retries").
#   sh gh-release.sh <tag> <title> <target-sha> <latest: true|false> <notes-file or -> <file>…
#   notes "-": release notes generated by GitHub.
# Order: draft → upload files → check names and sizes → publish. Until the last step nothing counts as released
# (security-tag.sh and the re-run checks ignore drafts), so a half release never appears.
# Every step is retried with growing pauses (10 s … 5 min, about 15 minutes in total).
# Re-run safe: an existing draft of the tag is completed, a published release with all files is accepted.
# Needs GH_TOKEN and GITHUB_REPOSITORY. GH_RELEASE_DELAY overrides the first pause (tests).
set -eu
tag="${1:?tag}"; title="${2:?title}"; target="${3:?target}"; latest="${4:?latest}"; notes="${5:?notes}"
shift 5
[ "$#" -gt 0 ] || { echo "::error::no release files given"; exit 1; }
case "$tag" in v[0-9]*) ;; *) echo "::error::unexpected tag $tag"; exit 1 ;; esac
case "$tag" in *[!0-9A-Za-z.-]*) echo "::error::unexpected tag $tag"; exit 1 ;; esac
case "$latest" in true|false) ;; *) echo "::error::latest must be true or false"; exit 1 ;; esac
for f in "$@"; do [ -f "$f" ] || { echo "::error::release file $f is missing"; exit 1; }; done

# Retry with growing pauses: 10, 20, 40, 80, 160, 300, 300 s
retry() {
  i=0; d="${GH_RELEASE_DELAY:-10}"
  until "$@"; do
    i=$((i + 1))
    [ "$i" -lt 8 ] || { echo "::error::GitHub keeps failing: $*"; return 1; }
    echo "::warning title=GitHub release::attempt $i failed ($*), next in ${d}s"
    sleep "$d"
    d=$((d * 2)); [ "$d" -le 300 ] || d=300
  done
}

# "<id> <draft>" of the release with this tag, drafts included ("" = none)
find_release() {
  gh api "repos/$GITHUB_REPOSITORY/releases?per_page=100" --jq ".[] | select(.tag_name == \"$tag\") | \"\(.id) \(.draft)\"" > rel.out
}
release_info() { retry find_release; head -n 1 rel.out; }

create_draft() {
  if [ "$notes" = - ]; then
    gh release create "$tag" --draft --verify-tag --title "$title" --target "$target" --generate-notes
  else
    gh release create "$tag" --draft --verify-tag --title "$title" --target "$target" --notes-file "$notes"
  fi
}

# Names and sizes of the uploaded files must match the local ones
check_assets() {
  gh api "repos/$GITHUB_REPOSITORY/releases/$1/assets?per_page=100" --jq '.[] | select(.state == "uploaded") | "\(.name) \(.size)"' | sort > assets.have
  : > assets.want
  for f in $files; do printf '%s %s\n' "$(basename "$f")" "$(wc -c < "$f" | tr -d ' ')" >> assets.want; done
  sort -o assets.want assets.want
  cmp -s assets.have assets.want
}

files="$*"
info="$(release_info)"
if [ -z "$info" ]; then
  # A failed create may still have created the draft – look again before every new try
  make() { info="$(release_info)"; [ -n "$info" ] || create_draft; }
  retry make
  info="$(release_info)"
  [ -n "$info" ] || { echo "::error::The draft of $tag was not created"; exit 1; }
fi
id="${info%% *}"; draft="${info#* }"

if [ "$draft" = false ] && check_assets "$id"; then
  echo "$tag is already released with all files – nothing to do"
  exit 0
fi
# Upload and check together: a file that arrived incomplete is uploaded again
upload() {
  # shellcheck disable=SC2086 # file names come from our own release/ folder (no spaces)
  gh release upload "$tag" $files --clobber && check_assets "$id"
}
retry upload
if [ "$draft" = true ]; then
  retry gh release edit "$tag" --draft=false --latest="$latest"
fi
retry check_assets "$id"
rm -f rel.out assets.have
echo "Released $tag with $(wc -l < assets.want | tr -d ' ') files (latest: $latest)"
rm -f assets.want
